// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize font loading outside the component to prevent render flicker
const { fontFamily: interFamily } = loadInter();



export type CeoMinimalistProps = Record<string, any>;

const CeoMinimalistAnimation: React.FC<CeoMinimalistProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryTextColor = "#ffffff",
  secondaryTextColor = "#888888",
  dotColor = "#444444",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Resolve parser-safe background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Configuration for the 3 stages
  const items = [
    { letter: "C", dot: ".", word1: "Chief", word2: "Change" },
    { letter: "E", dot: ".", word1: "Executive", word2: "Equals" },
    { letter: "O", dot: ".", word1: "Officer", word2: "Opportunity" },
  ];

  // Responsive typography sizing
  const fontSize = height * 0.13;
  const gapSize = height * 0.04;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "flex-start",
          width: "100%",
          height: "100%",
          paddingLeft: width * 0.22, // Balances the text block slightly off-center left
          gap: gapSize,
        }}
      >
        {items.map((item, index) => {
          // Stagger calculations
          const letterStart = index * 15;
          const word1Start = 60 + index * 10;
          const word1OutStart = 150 + index * 6;
          const word2Start = 180 + index * 10;

          // 1. Initial Letter & Dot Animation
          const letterInFrame = Math.max(0, frame - letterStart);
          const letterProgress = spring({ 
            frame: letterInFrame, 
            fps, 
            config: { damping: 16, stiffness: 120 } 
          });
          const letterY = interpolate(letterProgress, [0, 1], [40, 0]);
          const letterOpacity = interpolate(letterProgress, [0, 1], [0, 1]);

          // 2. First Set of Words Animation (Chief, Executive, Officer)
          const w1InFrame = Math.max(0, frame - word1Start);
          const w1InProgress = spring({ 
            frame: w1InFrame, 
            fps, 
            config: { damping: 16, stiffness: 100 } 
          });
          
          const w1OutFrame = Math.max(0, frame - word1OutStart);
          const w1OutProgress = spring({ 
            frame: w1OutFrame, 
            fps, 
            config: { damping: 14, stiffness: 90 } 
          });

          // Combines the entry slide with the exit slide up
          const w1Y = interpolate(w1InProgress, [0, 1], [30, 0]) + interpolate(w1OutProgress, [0, 1], [0, -30]);
          const w1OpIn = interpolate(w1InProgress, [0, 1], [0, 1]);
          const w1Opacity = interpolate(w1OutProgress, [0, 1], [w1OpIn, 0]);

          // 3. Second Set of Words Animation (Change, Equals, Opportunity)
          const w2InFrame = Math.max(0, frame - word2Start);
          const w2InProgress = spring({ 
            frame: w2InFrame, 
            fps, 
            config: { damping: 16, stiffness: 100 } 
          });

          const w2Y = interpolate(w2InProgress, [0, 1], [30, 0]);
          const w2Opacity = interpolate(w2InProgress, [0, 1], [0, 1]);

          return (
            <div
              key={index}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "baseline",
                transition: "none",
              }}
            >
              {/* Acronym Column */}
              <div
                style={{
                  width: width * 0.14,
                  fontSize,
                  fontWeight: 800,
                  letterSpacing: "-0.02em",
                  color: primaryTextColor,
                  opacity: letterOpacity,
                  transform: `translateY(${letterY}px)`,
                  display: "flex",
                  justifyContent: "flex-start",
                  transition: "none",
                }}
              >
                <span>{item.letter}</span>
                <span style={{ color: dotColor, marginLeft: "2px" }}>{item.dot}</span>
              </div>

              {/* Dynamic Words Column */}
              <div
                style={{
                  position: "relative",
                  display: "flex",
                  transition: "none",
                }}
              >
                {/* Invisible placeholder forces the parent to adopt correct height/baseline layout */}
                <span
                  style={{
                    fontSize,
                    fontWeight: 300,
                    opacity: 0,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                >
                  {/* Provide largest word for layout stabilization */}
                  Opportunity
                </span>

                {/* Word Set 1 */}
                <span
                  style={{
                    position: "absolute",
                    left: 0,
                    bottom: 0,
                    fontSize,
                    fontWeight: 300,
                    letterSpacing: "-0.01em",
                    color: secondaryTextColor,
                    opacity: w1Opacity,
                    transform: `translateY(${w1Y}px)`,
                    whiteSpace: "nowrap",
                    transition: "none",
                  }}
                >
                  {item.word1}
                </span>

                {/* Word Set 2 */}
                <span
                  style={{
                    position: "absolute",
                    left: 0,
                    bottom: 0,
                    fontSize,
                    fontWeight: 300,
                    letterSpacing: "-0.01em",
                    color: primaryTextColor, // Emphasize the new meaning
                    opacity: w2Opacity,
                    transform: `translateY(${w2Y}px)`,
                    whiteSpace: "nowrap",
                    transition: "none",
                  }}
                >
                  {item.word2}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default CeoMinimalistAnimation;